// === Tab: mySketch.js ===
let timer=0;
let palette = ["#2c695a", "#4ad6af", "#7facc6", "#4e93cc", "#f6684f", "#ffd300"];
let palette1 =["#8D95A6", "#0A7360", "#F28705", "#D98825", "#F2F2F2"];
let palette2 = ["#ffc252","#fff95e","#ff4b44","#1c7fff","#8738ff"];
let palette3 =["#01403A","#025949","#D99152","#BF6849","#734136"];
let palette4=["#D9D7D8", "#3B5159", "#5D848C", "#7CA2A6", "#262321"];
let palette5=["#906FA6", "#025951", "#252625", "#D99191", "#F2F2F2"];
let palette6=["#023059", "#459DBF", "#87BF60", "#D9D16A", "#F2F2F2"];


function setup() 
{
	createCanvas(windowWidth, windowHeight,WEBGL);
	background("#fffceb");
}



function draw() {
    rotateX(timer / 90);
    rotateY(timer / 20);
    rotateZ(timer / 90);
    timer++;
    orbitControl();

    for (let x = -50; x < 50; x++) { // X軸のグリッドを作成
        for (let y = -50; y < 50; y++) { // Y軸のグリッドを作成
            push();
            translate(x * 20, y * 20, 0);

            // 球体の色を決定
            if (timer % 10 == 0 && timer < 61) {
                let col;
                if (x == 0 && y == 0) 
                    col = color(random(palette));
                else if (x == 0 && y == 1 && timer < 30) 
                    col = color(random(palette2));
                else if (x == 0 && y == -1 && timer < 30) 
                    col = color(random(palette3));
                else 
                    col = color(0, 0, 0); // Default to black for other conditions

                col.setAlpha(200); // Set alpha
                stroke(col); // Apply the color with alpha to stroke
                sphere(random(25));
            } 
            else if (timer >= 61 && timer < 77) {
                // For the touch of light effect, choose a random color from any palette
                var col = color(random(palette4)); // Choose a color from palette4 as an example
                col.setAlpha(20); // Set a lower alpha for the light effect
                stroke(col);
                noFill();
                translate(200, 100, -500);
                strokeWeight(0.5);
                for (let i = 0; i < 3; i++) {
                    rotateX(timer * 4);
                    box(x * 15, -900 + x * 15, 10);
                }
            } 
            else if (timer < 77) {
                // For the giant circles/rings around the spheres
                var col;
                if (x == 0 && y == 0) 
                    col = color(random(palette5));
                else if (x == 0 && y == 1 && timer < 30) 
                    col = color(random(palette6));
                else if (x == 0 && y == -1 && timer < 30) 
                    col = color(random(palette)); // Using palette for variation
                else 
                    col = color(0, 0, 0); // Default to black for other conditions

                col.setAlpha(200); // Set alpha
                stroke(col);
                strokeWeight(0.5);
                noFill();
                circle(0, 0, 200);
            }
            pop();
        }
    }
}

